<?php require_once __DIR__.'/includes/auth.php';$sent=false;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$name=clean_text($_POST['name']??'',120,true,'Name');$email=strtolower(clean_text($_POST['email']??'',190,true,'Email'));$message=clean_text($_POST['message']??'',2000,true,'Message');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||text_length($message)<10)throw new RuntimeException('Please enter a valid name, email and message.');$sent=true;}catch(RuntimeException $e){$error=$e->getMessage();}}$pageTitle='Contact LocalConnect';require __DIR__.'/includes/header.php';?>
<main class="container py-5"><div class="row g-4 justify-content-center"><div class="col-lg-5"><span class="eyebrow">CONTACT</span><h1 class="fw-bold mt-2">How can we help?</h1><p class="text-secondary">For this local MVP, the contact form validates your message but does not send email until SMTP/email credentials are configured.</p><div class="soft-card p-4"><i class="fa-solid fa-shield-halved text-primary me-2"></i><strong>Safety note</strong><p class="text-muted mt-2 mb-0">Use the Report Profile option for suspicious listings so administrators can review them inside the platform.</p></div></div><div class="col-lg-6"><div class="soft-card p-4 p-md-5"><?php if($sent):?><div class="alert alert-success">Message validated successfully. Email delivery can be enabled later with an SMTP provider.</div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="mb-3"><label class="form-label">Name</label><input class="form-control" name="name" required maxlength="120"></div><div class="mb-3"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required maxlength="190"></div><div class="mb-3"><label class="form-label">Message</label><textarea class="form-control" name="message" rows="6" minlength="10" maxlength="2000" required></textarea></div><button class="btn btn-primary">Validate message</button></form></div></div></div></main>
